// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 n1, uint256 n2, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        ts = bound(ts, 1, type(uint256).max / 2);
        n1 = bound(n1, 0, type(uint64).max);
        n1 = n1 - (n1 % 15) + 1; // ensure first call does NOT trigger the payout branch
        n2 = bound(n2, 0, type(uint64).max);

        vm.deal(actor, 10 ether);
        vm.warp(ts);
        vm.roll(n1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // second call at the SAME timestamp: must revert since block.timestamp > pastBlockTime fails
        vm.deal(actor, 10 ether);
        vm.roll(n2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "second call in same timestamp must revert");
    }
}
